export type GuideSection = { title: string; purpose: string; principle: string; formula: string; interpretation: string; limits: string; recommendation: string; steps: string }
const common = {
  'zh-TW': { purpose: '說明目前頁面的用途與結果。', principle: '以所選資料與統計假設為判讀基礎。', formula: '請參考頁面指標與圖表註記。', interpretation: '綜合數值、圖表與工程知識判讀。', limits: '結果描述所選樣本，不代表母體或因果結論。', recommendation: '決策前確認資料品質與分析假設。', steps: '選擇資料或模型 → 執行分析 → 檢查圖表與指標 → 依建議驗證並保存結果。' },
  en: { purpose: 'Explain the purpose and results of this page.', principle: 'Interpret results using the selected data and statistical assumptions.', formula: 'Refer to the metrics and chart annotations on the page.', interpretation: 'Combine numerical results, charts, and engineering knowledge.', limits: 'Results describe the selected sample and do not prove population or causality.', recommendation: 'Verify data quality and assumptions before decisions.', steps: 'Select data or a model → run the analysis → inspect charts and metrics → validate recommendations and save the result.' },
  'es-MX': { purpose: 'Explica el propósito y los resultados de esta página.', principle: 'Interpreta con los datos seleccionados y los supuestos estadísticos.', formula: 'Consulta las métricas y anotaciones del gráfico.', interpretation: 'Combina resultados numéricos, gráficos y conocimiento de ingeniería.', limits: 'Los resultados describen la muestra y no prueban población ni causalidad.', recommendation: 'Verifica calidad de datos y supuestos antes de decidir.', steps: 'Selecciona datos o modelo → ejecuta el análisis → revisa gráficos y métricas → valida recomendaciones y guarda el resultado.' },
} as const
const topics: Record<string, Partial<Record<keyof typeof common, Partial<GuideSection>>>> = {
  project: { 'zh-TW': { purpose: '集中檢視專案的資料集、模型、分析結果、驗證紀錄與 Gate 狀態，確認是否具備進入後續分析的條件。', principle: '本頁彙整各模組已產生的狀態與結果，不重新計算統計模型；實際統計結論仍應回到對應分析頁確認。', formula: '本頁不產生新的統計公式；各項指標沿用資料健檢、SPC、模型配適、模擬與驗證頁面的計算結果。', interpretation: '優先查看資料品質、Gate 狀態、模型就緒情況與未確認項目。warning 表示需注意，blocked 表示不可直接進入後續流程，confirmed 表示已完成確認。', limits: '總覽內容取決於目前已載入及已儲存的專案資料；頁面狀態不代表統計結論，也不能取代原始分析、模型驗證或工程審查。', recommendation: '先確認資料集版本、資料品質、規格與管制界線，再檢查模型和驗證狀態；存在未確認或 blocked 項目時，先處理後再產生報告或執行模擬。', steps: '1. 確認專案名稱與版本。 2. 檢查資料集是否已載入且狀態正常。 3. 查看模型、報告、模擬與驗證紀錄。 4. 檢查各項 Gate 的通過、待確認或阻擋狀態。 5. 依缺失項目返回資料匯入、製程定義或分析頁處理。 6. 完成確認後儲存專案。' }, en: { purpose: 'Review the project dataset, models, analysis results, validation records, and gate status to determine whether the project is ready for downstream analysis.', principle: 'This page summarizes states and results produced by modules; it does not recalculate statistical models. Confirm statistical conclusions on the relevant analysis page.', formula: 'No new formulas are calculated here; metrics come from data checks, SPC, model fitting, simulation, and validation pages.', interpretation: 'Prioritize data quality, gate status, model readiness, and unconfirmed items. warning means attention is needed, blocked prevents downstream work, and confirmed indicates review completed.', limits: 'The overview depends on data currently loaded and saved in the project. Status is not a statistical conclusion and does not replace analysis, validation, or engineering review.', recommendation: 'Verify dataset version, quality, specifications, and control limits before reviewing models and validation. Resolve unconfirmed or blocked items before reports or simulation.', steps: '1. Confirm the project name and version. 2. Check that the dataset is loaded and healthy. 3. Review model, report, simulation, and validation records. 4. Check each gate for passed, pending, or blocked status. 5. Return to import, process definition, or analysis pages to resolve gaps. 6. Save the project after review.' }, 'es-MX': { purpose: 'Revisa datos, modelos, resultados, validaciones y estado de gates para saber si el proyecto está listo para el análisis posterior.', principle: 'Esta página resume estados y resultados de los módulos; no recalcula modelos estadísticos. Confirma las conclusiones en la página de análisis correspondiente.', formula: 'No calcula fórmulas nuevas; las métricas provienen de calidad de datos, SPC, ajuste de modelos, simulación y validación.', interpretation: 'Prioriza calidad de datos, gates, preparación del modelo y elementos no confirmados. warning requiere atención, blocked impide continuar y confirmed indica revisión completada.', limits: 'El resumen depende de los datos cargados y guardados. El estado no es una conclusión estadística ni sustituye análisis, validación o revisión de ingeniería.', recommendation: 'Verifica versión, calidad, especificaciones y límites de control antes de revisar modelos y validación. Resuelve elementos no confirmados o bloqueados antes de informes o simulación.', steps: '1. Confirma nombre y versión del proyecto. 2. Comprueba que el conjunto de datos esté cargado y correcto. 3. Revisa modelos, informes, simulaciones y validaciones. 4. Comprueba cada gate: aprobado, pendiente o bloqueado. 5. Vuelve a importación, definición del proceso o análisis para corregir faltantes. 6. Guarda el proyecto al terminar.' } },
  dataImport: { 'zh-TW': { purpose: '匯入 CSV 或支援格式，確認資料筆數、欄位型態、輸入／輸出角色、時間欄位與資料品質，建立後續分析使用的資料集。', principle: '本頁進行描述性統計、欄位型態辨識、缺值與異常檢查，以及候選分布配適，作為 SPC、模型配適與蒙地卡羅的資料基礎。', formula: '平均值 μ=Σxᵢ／n；樣本標準差 s=√[Σ(xᵢ−x̄)²／(n−1)]；缺值率=缺值數／總列數×100%；類別比例=類別筆數／總筆數×100%。', interpretation: '查看各欄位的 n、最小值、最大值、平均值、標準差、最佳分布與問題數。warning 需人工判斷，blocked 或嚴重問題應先處理；最佳分布只是樣本配適結果。', limits: '檢查結果只反映目前匯入樣本。欄位角色、單位或時間順序設定錯誤會使後續分析失真；摘要統計與分布配適不代表母體或因果結論。', recommendation: '先確認資料來源、單位、時間戳、量測系統與欄位角色，優先修正缺值、重複、時間錯序、單位混用與型態錯誤，再進行模型、SPC 或模擬。', steps: '1. 選擇或拖放資料檔案。 2. 確認資料列數、欄位數與欄位名稱。 3. 檢查欄位型態、時間格式與識別欄位。 4. 指定 input、output、時間、零件與操作者欄位。 5. 檢視資料品質報告。 6. 執行建模前資料健檢，查看統計摘要與最佳分布。 7. 修正嚴重問題或確認可接受警告。 8. 儲存資料集與版本後進入製程定義或分析。' }, en: { purpose: 'Import CSV or supported formats, verify row counts, field types, input/output roles, time fields, and data quality, and create the dataset used by downstream analysis.', principle: 'The page performs descriptive statistics, type detection, missingness and anomaly checks, and candidate distribution fitting as the basis for SPC, model fitting, and Monte Carlo.', formula: 'Mean μ=Σxᵢ/n; sample standard deviation s=√[Σ(xᵢ−x̄)²/(n−1)]; missing rate=missing rows/total rows×100%; category share=category count/total count×100%.', interpretation: 'Review n, min, max, mean, standard deviation, best distribution, and issue count for each field. warning requires review; blocked or critical issues should be resolved first. A best distribution is only a sample fit.', limits: 'Checks describe the imported sample. Incorrect roles, units, or time ordering can distort downstream results; summaries and fits do not prove population behavior or causality.', recommendation: 'Verify source, units, timestamps, measurement system, and field roles. Fix missing, duplicate, out-of-order, mixed-unit, and type errors before models, SPC, or simulation.', steps: '1. Select or drop a data file. 2. Confirm rows, columns, and names. 3. Check types, time format, and identifiers. 4. Assign input, output, time, part, and operator fields. 5. Review the data-quality report. 6. Run the pre-model check and review summaries and best distributions. 7. Resolve critical issues or accept warnings. 8. Save the dataset and version before process definition or analysis.' }, 'es-MX': { purpose: 'Importa CSV u otros formatos admitidos, verifica filas, tipos, roles de entrada/salida, tiempo y calidad, y crea el conjunto usado por los análisis.', principle: 'La página calcula estadística descriptiva, detecta tipos, faltantes y anomalías, y ajusta distribuciones candidatas para SPC, modelos y Monte Carlo.', formula: 'Media μ=Σxᵢ/n; desviación estándar muestral s=√[Σ(xᵢ−x̄)²/(n−1)]; tasa de faltantes=faltantes/total×100%; proporción=conteo de categoría/total×100%.', interpretation: 'Revisa n, mínimo, máximo, media, desviación, mejor distribución y problemas de cada campo. warning requiere revisión; blocked o problemas críticos deben resolverse. La mejor distribución es solo un ajuste muestral.', limits: 'Los controles describen la muestra importada. Roles, unidades u orden temporal incorrectos pueden distorsionar resultados; los resúmenes no prueban población ni causalidad.', recommendation: 'Verifica fuente, unidades, marcas de tiempo, sistema de medición y roles. Corrige faltantes, duplicados, orden temporal, unidades mezcladas y tipos antes de modelos, SPC o simulación.', steps: '1. Selecciona o arrastra un archivo. 2. Confirma filas, columnas y nombres. 3. Revisa tipos, tiempo e identificadores. 4. Asigna campos de entrada, salida, tiempo, pieza y operador. 5. Revisa el informe de calidad. 6. Ejecuta la revisión previa al modelo y consulta resúmenes y distribuciones. 7. Corrige problemas críticos o acepta avisos. 8. Guarda el conjunto y su versión antes de definir el proceso o analizar.' } },
  processDefine: { 'zh-TW': { purpose: '建立製程分析契約：定義輸出與 LSL／USL／中心值、輸入參數與單位、管制界限、操作範圍、品質複查、異常情境及分析資料包。', principle: '規格限描述客戶／工程要求；管制界限描述製程統計穩定性；操作範圍限制模型可安全外推的輸入區域。', formula: '能力指標常用 Cp=(USL−LSL)/(6σ)、Cpk=min((USL−μ)/(3σ),(μ−LSL)/(3σ))；控制界線通常為中心線 ± 3σ。', interpretation: '先設定輸出規格與中心值，再確認每個輸入的工程範圍與單位；複查結果後處理異常情境，最後產生資料包供模型、SPC 與模擬使用。', limits: '缺少規格、單位或操作範圍會使能力、異常與模擬判定失真；設定值是工程假設，不代表因果關係。', recommendation: '逐項核對輸入／輸出角色、LSL／USL 順序、中心值是否位於規格內、管制界線來源與資料包版本。', steps: '1. 設定輸出欄位與 LSL／USL／中心值。 2. 為每個輸入確認單位、名目值與操作上下限。 3. 檢查或輸入管制界限。 4. 執行規格後品質複查並修正警告。 5. 檢視並確認異常情境。 6. 產生分析資料包後再進入模型、SPC 或蒙地卡羅。' }, en: { purpose: 'Create the process-analysis contract: define output limits and center value, input parameters and units, control limits, operating ranges, quality review, anomaly scenarios, and the analysis package.', principle: 'Specification limits represent customer or engineering requirements; control limits represent statistical stability; operating ranges bound safe model extrapolation.', formula: 'Common capability indices are Cp=(USL−LSL)/(6σ) and Cpk=min((USL−μ)/(3σ),(μ−LSL)/(3σ)); control limits are commonly center line ± 3σ.', interpretation: 'Set output specifications and center value first, then verify each input range and unit; review quality, handle anomaly scenarios, and generate the package for models, SPC, and simulation.', limits: 'Missing limits, units, or operating ranges can distort capability, anomaly, and simulation results; settings are engineering assumptions, not causal proof.', recommendation: 'Check input/output roles, LSL/USL order, center value within limits, control-limit source, and package version.', steps: '1. Set output field, LSL, USL, and center value. 2. Confirm units, nominal values, and operating limits for every input. 3. Review or enter control limits. 4. Run the post-spec quality review and resolve warnings. 5. Review and confirm anomaly scenarios. 6. Generate the analysis package before models, SPC, or Monte Carlo.' }, 'es-MX': { purpose: 'Crea el contrato de análisis: define límites y centro de salida, parámetros y unidades de entrada, límites de control, rangos operativos, revisión de calidad, anomalías y paquete de análisis.', principle: 'Los límites de especificación representan requisitos; los límites de control representan estabilidad estadística; los rangos operativos limitan la extrapolación segura del modelo.', formula: 'Índices comunes: Cp=(USL−LSL)/(6σ) y Cpk=min((USL−μ)/(3σ),(μ−LSL)/(3σ)); límites de control: línea central ± 3σ.', interpretation: 'Configura primero especificaciones y centro de salida; valida rangos y unidades, revisa calidad, trata anomalías y genera el paquete para modelos, SPC y simulación.', limits: 'Sin límites, unidades o rangos, los resultados pueden distorsionarse; son supuestos de ingeniería, no prueba causal.', recommendation: 'Verifica roles, orden LSL/USL, centro dentro de límites, fuente de límites de control y versión del paquete.', steps: '1. Configura salida, LSL, USL y centro. 2. Confirma unidades, nominales y rangos de cada entrada. 3. Revisa límites de control. 4. Ejecuta la revisión de calidad y corrige avisos. 5. Revisa y confirma anomalías. 6. Genera el paquete antes de modelos, SPC o Monte Carlo.' } },
  processFlow: { 'zh-TW': { purpose: '以流程節點串接資料匯入、製程定義、SPC、模型配適、模擬、驗證與報告，呈現執行順序、依賴關係與結果狀態。', principle: '流程本身不重新計算統計量，而是依節點順序傳遞資料與分析結果；上游資料品質、規格與模型假設會影響所有下游結果。', formula: '本頁不產生新的統計公式；各節點沿用其對應頁面的公式與指標。', interpretation: '先確認流程方向與節點依賴。成功表示已產生結果，warning 表示需人工檢查，blocked 表示前置條件未滿足；流程連線不代表結果已通過驗證。', limits: '流程圖只表示已設定或執行的工作關係，不代表節點結果正確或具因果性。若節點輸入版本變更，既有下游結果可能需要重新執行。', recommendation: '維持單一且清楚的資料流向，避免循環或未定義輸入；記錄每個節點的資料集、模型版本、參數與執行時間，更新後重新檢查受影響節點。', steps: '1. 建立或開啟製程流程。 2. 新增資料、分析、模型、模擬、驗證或報告節點。 3. 依執行順序連接節點。 4. 指定每個節點的輸入、輸出與參數。 5. 檢查缺少輸入、設定或前置 Gate 的節點。 6. 執行節點並查看成功、警告或阻擋狀態。 7. 檢查版本、來源與結果追溯性。 8. 儲存流程版本，必要時重新執行下游節點。' }, en: { purpose: 'Connect data import, process definition, SPC, model fitting, simulation, validation, and reporting nodes to show execution order, dependencies, and result status.', principle: 'The flow does not recalculate statistics; it passes data and results in node order. Upstream data quality, specifications, and model assumptions affect downstream results.', formula: 'No new formulas are calculated here; each node uses the formulas and metrics of its corresponding page.', interpretation: 'Confirm flow direction and dependencies first. Success means a result was produced, warning requires review, and blocked means a prerequisite is missing. A connection does not mean the result is validated.', limits: 'The diagram represents configured or executed work relationships, not correctness or causality. Changing an input version may require downstream nodes to run again.', recommendation: 'Keep one clear data direction and avoid cycles or undefined inputs. Record dataset, model version, parameters, and run time for each node; recheck affected nodes after updates.', steps: '1. Create or open a process flow. 2. Add data, analysis, model, simulation, validation, or report nodes. 3. Connect nodes in execution order. 4. Assign inputs, outputs, and parameters. 5. Check for missing inputs, settings, or gate prerequisites. 6. Run nodes and review success, warning, or blocked status. 7. Verify versions, sources, and traceability. 8. Save the flow version and rerun downstream nodes when needed.' }, 'es-MX': { purpose: 'Conecta nodos de importación, definición de proceso, SPC, modelos, simulación, validación e informes para mostrar orden, dependencias y estados.', principle: 'El flujo no recalcula estadísticas; transmite datos y resultados en orden. La calidad, especificaciones y supuestos aguas arriba afectan los resultados posteriores.', formula: 'No calcula fórmulas nuevas; cada nodo usa las métricas y fórmulas de su página.', interpretation: 'Confirma dirección y dependencias. Éxito indica resultado generado, warning requiere revisión y blocked indica un prerrequisito faltante; una conexión no implica validación.', limits: 'El diagrama representa relaciones configuradas o ejecutadas, no exactitud ni causalidad. Cambiar una versión de entrada puede requerir repetir nodos posteriores.', recommendation: 'Mantén un flujo claro sin ciclos ni entradas indefinidas. Registra conjunto de datos, versión del modelo, parámetros y hora; revisa nodos afectados tras cambios.', steps: '1. Crea o abre un flujo. 2. Añade nodos de datos, análisis, modelo, simulación, validación o informe. 3. Conéctalos en orden. 4. Asigna entradas, salidas y parámetros. 5. Busca entradas, ajustes o gates faltantes. 6. Ejecuta nodos y revisa estados. 7. Verifica versiones, fuentes y trazabilidad. 8. Guarda la versión y repite nodos posteriores cuando sea necesario.' } },
  copula: { 'zh-TW': { purpose: '分析多個 input／output 欄位的相依結構，將各欄位邊際分布與欄位間相關性分開建模，支援保留相關性的聯合抽樣與蒙地卡羅模擬。', principle: '依 Sklar 定理將聯合分布拆成邊際分布與相依結構；邊際分布描述單一欄位，Copula 描述欄位共同變動方式。', formula: 'F(x₁,…,xₚ)=C(F₁(x₁),…,Fₚ(xₚ))；Pearson ρ=Cov(X,Y)／(σXσY)；Spearman 與 Kendall 衡量排序或單調相依。', interpretation: '相關矩陣顯示正、負相關與強度；散佈圖檢查非線性關係；尾端同時聚集表示尾端相依，可能影響 NG 風險。聯合抽樣後應確認邊際分布與相關性仍接近原始資料。', limits: '樣本量不足、缺值、離群值或製程不穩定會使相依性估計不可靠。相關性不代表因果；錯誤的 Copula 或邊際分布可能放大或低估聯合風險。', recommendation: '先處理資料品質並確認欄位時間與批次一致，再選擇相關性方法與 Copula。使用於蒙地卡羅前，比較抽樣前後分布、相關矩陣與尾端行為；結果敏感時保留獨立抽樣作為對照。', steps: '1. 確認資料集與欄位角色已設定。 2. 選擇要分析的數值欄位。 3. 檢查邊際分布、缺值與離群值。 4. 計算 Pearson、Spearman 或 Kendall 相關性。 5. 選擇或比較 Copula 類型。 6. 檢查相關矩陣是否對稱且為半正定。 7. 執行聯合抽樣或傳遞至蒙地卡羅。 8. 比較抽樣前後邊際分布、相關性與尾端行為。 9. 儲存 Copula 設定與版本。' }, en: { purpose: 'Analyze dependence among input/output fields by separating marginal distributions from dependence, enabling dependence-preserving joint sampling and Monte Carlo.', principle: 'By Sklar’s theorem, a joint distribution is decomposed into marginals and dependence; marginals describe each field and the copula describes co-movement.', formula: 'F(x₁,…,xₚ)=C(F₁(x₁),…,Fₚ(xₚ)); Pearson ρ=Cov(X,Y)/(σXσY); Spearman and Kendall measure rank or monotonic dependence.', interpretation: 'Correlation matrices show direction and strength; scatter or dependence plots reveal nonlinear structure. Joint tail clustering indicates tail dependence and can affect NG risk. Verify marginals and correlations after joint sampling.', limits: 'Small samples, missingness, outliers, or unstable processes make dependence estimates unreliable. Correlation is not causality; incorrect copula or marginals can over- or underestimate joint risk.', recommendation: 'Clean data and align time and batch before choosing a dependence method and copula. Before Monte Carlo, compare pre/post-sampling marginals, correlations, and tail behavior; retain an independent-sampling baseline when sensitive.', steps: '1. Confirm dataset and field roles. 2. Select numeric fields. 3. Check marginals, missingness, and outliers. 4. Calculate Pearson, Spearman, or Kendall dependence. 5. Select or compare copula types. 6. Check that the correlation matrix is symmetric and positive semidefinite. 7. Run joint sampling or pass settings to Monte Carlo. 8. Compare pre/post marginals, dependence, and tails. 9. Save the copula settings and version.' }, 'es-MX': { purpose: 'Analiza dependencia entre entradas y salidas separando distribuciones marginales y dependencia para muestreo conjunto y Monte Carlo.', principle: 'Según Sklar, la distribución conjunta se separa en marginales y dependencia; las marginales describen campos y la cópula su movimiento conjunto.', formula: 'F(x₁,…,xₚ)=C(F₁(x₁),…,Fₚ(xₚ)); Pearson ρ=Cov(X,Y)/(σXσY); Spearman y Kendall miden dependencia de rangos o monótona.', interpretation: 'La matriz muestra dirección e intensidad; gráficos revelan relaciones no lineales. La concentración en colas indica dependencia extrema y puede afectar riesgo NG. Verifica marginales y correlaciones tras muestrear.', limits: 'Muestras pequeñas, faltantes, atípicos o procesos inestables vuelven poco fiable la dependencia. Correlación no es causalidad; una cópula o marginal incorrecta puede sesgar el riesgo conjunto.', recommendation: 'Limpia datos y alinea tiempo y lote antes de elegir método y cópula. Antes de Monte Carlo compara marginales, correlaciones y colas; conserva muestreo independiente como referencia si hay sensibilidad.', steps: '1. Confirma datos y roles. 2. Selecciona campos numéricos. 3. Revisa marginales, faltantes y atípicos. 4. Calcula Pearson, Spearman o Kendall. 5. Elige o compara cópulas. 6. Comprueba matriz simétrica y semidefinida positiva. 7. Ejecuta muestreo conjunto o pasa ajustes a Monte Carlo. 8. Compara marginales, dependencia y colas antes/después. 9. Guarda configuración y versión.' } },
  prediction: { 'zh-TW': { purpose: '使用已配適且通過基本驗證的模型，輸入一組或多組製程條件，預測輸出值並判斷是否落在規格範圍內。', principle: '模型依輸入變數與估計參數計算條件式預測；預測值是模型估計，不等於實際量測，預測區間還包含殘差與未解釋變異。', formula: '線性：ŷ=β₀+Σβⱼxⱼ；二次：ŷ=β₀+Σβⱼxⱼ+Σβⱼⱼxⱼ²+Σβⱼₖxⱼxₖ；誤差 e=y−ŷ；合格判定：LSL≤ŷ≤USL。', interpretation: '查看預測值是否落在規格內，並確認預測區間是否跨越界線。輸入接近訓練範圍邊界時不確定性通常較高；超出範圍應標示為外推。', limits: '預測品質受模型、資料品質、輸入範圍、共線性與假設影響；互動預測不代表因果，也不能取代實際量測或驗證實驗。', recommendation: '優先使用已驗證模型與合理操作範圍。預測接近規格界線或輸入變更較大時，先進行蒙地卡羅或實驗驗證。', steps: '1. 選擇資料集與已儲存模型版本。 2. 確認輸入欄位、單位、規格與適用範圍。 3. 輸入或調整各 input 值。 4. 檢查缺值、型態錯誤與範圍警告。 5. 執行預測。 6. 查看輸出值、規格判定、預測區間與外推警告。 7. 比較不同輸入情境。 8. 儲存預測情境，必要時送往模擬或驗證實驗。' }, en: { purpose: 'Use a fitted and basically validated model to predict outputs for one or more process conditions and check whether they meet specifications.', principle: 'The model computes conditional predictions from inputs and estimated parameters. A prediction is not a measurement; prediction intervals also include residual and unexplained variation.', formula: 'Linear: ŷ=β₀+Σβⱼxⱼ; quadratic: ŷ=β₀+Σβⱼxⱼ+Σβⱼⱼxⱼ²+Σβⱼₖxⱼxₖ; error e=y−ŷ; pass if LSL≤ŷ≤USL.', interpretation: 'Check the prediction against limits and whether its interval crosses a limit. Uncertainty is often higher near training boundaries; outside-range inputs are extrapolation.', limits: 'Quality depends on model, data, range, collinearity, and assumptions. Interactive predictions do not prove causality or replace measurements and experiments.', recommendation: 'Use validated models within their operating range. For predictions near limits or large input changes, run Monte Carlo or a physical validation experiment first.', steps: '1. Select a dataset and saved model version. 2. Confirm input fields, units, specifications, and applicability range. 3. Enter or adjust inputs. 4. Check missing values, type errors, and range warnings. 5. Run prediction. 6. Review output, spec status, interval, and extrapolation warning. 7. Compare input scenarios. 8. Save the scenario and send it to simulation or validation when needed.' }, 'es-MX': { purpose: 'Usa un modelo ajustado y validado para predecir salidas bajo condiciones del proceso y comprobar especificaciones.', principle: 'El modelo calcula predicciones condicionales con entradas y parámetros estimados. La predicción no es una medición; el intervalo incluye residuo y variación no explicada.', formula: 'Lineal: ŷ=β₀+Σβⱼxⱼ; cuadrático: ŷ=β₀+Σβⱼxⱼ+Σβⱼⱼxⱼ²+Σβⱼₖxⱼxₖ; error e=y−ŷ; conforme si LSL≤ŷ≤USL.', interpretation: 'Compara la predicción con límites y comprueba si el intervalo cruza alguno. La incertidumbre suele crecer en los bordes del entrenamiento; fuera del rango es extrapolación.', limits: 'Depende del modelo, calidad, rango, colinealidad y supuestos. No prueba causalidad ni sustituye mediciones o experimentos.', recommendation: 'Usa modelos validados dentro del rango operativo. Cerca de límites o con grandes cambios, ejecuta Monte Carlo o validación física.', steps: '1. Selecciona datos y versión guardada. 2. Confirma campos, unidades, especificaciones y rango. 3. Introduce o ajusta entradas. 4. Revisa faltantes, tipos y avisos de rango. 5. Ejecuta predicción. 6. Revisa salida, estado, intervalo y extrapolación. 7. Compara escenarios. 8. Guarda el escenario y envíalo a simulación o validación cuando proceda.' } },
  approval: { 'zh-TW': { purpose: '審核資料、模型、分析結果、實驗與報告的證據狀態，確認 Gate 與追溯紀錄後，決定是否升級、發布或退回處理。', principle: '本頁不重新計算統計模型，而是確認結果是否具備來源、適用假設、驗證紀錄與工程審查支持；證據狀態不等同統計顯著性。', formula: '本頁不產生新的統計公式；審核沿用來源分析頁面的指標與判定規則。', interpretation: 'unverified 表示尚未確認，confirmed 表示完成審核，blocked 表示存在不可忽略的前置問題。狀態變更應保留審核者、時間與理由。', limits: '審核狀態不代表母體結論、因果關係或模型永久正確；資料、模型、規格或報告更新後可能需要重新審核。', recommendation: '高風險項目採雙人或分級審核；發布前確認 evidence、Gate、版本、限制與備註完整，未確認或 blocked 項目不得直接作為正式生產決策依據。', steps: '1. 開啟待審核的資料、模型、分析或報告。 2. 查看 evidence ID、來源、版本、時間與狀態。 3. 檢查支持證據、統計結果、限制與未確認項目。 4. 確認資料集、模型、篩選條件與報告 metadata 可追溯。 5. 檢查 Gate 是否通過、待確認或阻擋。 6. 指定審核結果、審核者與備註。 7. 標記 confirmed、退回修正或維持 unverified。 8. 通過後再升級版本、發布報告或交由下游使用。' }, en: { purpose: 'Review evidence status for data, models, analyses, experiments, and reports; confirm gates and traceability before upgrading, releasing, or returning an item.', principle: 'This page does not recalculate models. It checks source, assumptions, validation records, and engineering review; evidence status is not statistical significance.', formula: 'No new formulas are calculated here; review uses the metrics and decision rules of the source analysis page.', interpretation: 'unverified means not reviewed, confirmed means review completed, and blocked means a material prerequisite issue exists. Record reviewer, time, and reason for every status change.', limits: 'Approval status does not prove population behavior, causality, or permanent correctness. Updates to data, models, specifications, or reports may require reapproval.', recommendation: 'Use dual or tiered review for high-risk items. Before release, verify evidence, gates, versions, limitations, and notes; never use unverified or blocked items directly for production decisions.', steps: '1. Open the data, model, analysis, or report for review. 2. Inspect evidence ID, source, version, time, and status. 3. Check supporting evidence, results, limitations, and unconfirmed items. 4. Verify dataset, model, filters, and report metadata are traceable. 5. Check gates for passed, pending, or blocked. 6. Record decision, reviewer, and notes. 7. Mark confirmed, return for correction, or keep unverified. 8. Upgrade, release, or pass downstream only after approval.' }, 'es-MX': { purpose: 'Revisa el estado de evidencia de datos, modelos, análisis, experimentos e informes; confirma gates y trazabilidad antes de publicar o devolver.', principle: 'No recalcula modelos; comprueba fuentes, supuestos, validaciones y revisión de ingeniería. El estado de evidencia no equivale a significancia estadística.', formula: 'No calcula fórmulas nuevas; usa métricas y reglas de la página de origen.', interpretation: 'unverified no revisado, confirmed revisión completada y blocked prerrequisito material pendiente. Registra revisor, hora y motivo de cada cambio.', limits: 'La aprobación no prueba población, causalidad ni corrección permanente. Cambios en datos, modelos, especificaciones o informes pueden requerir nueva revisión.', recommendation: 'Usa revisión doble o por niveles para alto riesgo. Antes de publicar verifica evidencia, gates, versiones, límites y notas; no uses elementos no confirmados o bloqueados para decisiones de producción.', steps: '1. Abre el elemento pendiente. 2. Revisa ID, fuente, versión, hora y estado. 3. Comprueba evidencia, resultados, límites y pendientes. 4. Verifica trazabilidad de datos, modelo, filtros y metadatos. 5. Comprueba gates aprobados, pendientes o bloqueados. 6. Registra decisión, revisor y notas. 7. Marca confirmado, devuelve para corrección o mantiene no verificado. 8. Publica o pasa a otros módulos solo tras aprobar.' } },
  dataAssets: { 'zh-TW': { purpose: '集中管理資料集、模型、報告、模擬、驗證實驗與分析資料包，維持版本、來源與使用狀態的可追溯性。', principle: '本頁不重新計算統計模型，而是管理分析所使用的資料與結果物件；資產版本與來源一致性是分析可重現的重要條件。', formula: '本頁不產生新的統計公式；各資產沿用來源分析頁面的指標與計算方式。', interpretation: '確認資產類型、版本、狀態、來源與相依關係。active 表示可使用，archived 表示保留但不建議新增使用，unverified 表示尚未完成審核。', limits: '資產清單不代表內容一定正確或最新。刪除、封存或替換可能影響下游流程、報告與追溯；metadata 不等同統計驗證。', recommendation: '使用前確認版本、來源、篩選條件、建立時間與審核狀態；刪除前檢查依賴關係，保留正式發布版本與必要來源檔案。', steps: '1. 開啟資料資產頁面。 2. 依資產類型、版本、狀態或建立時間篩選。 3. 查看資產 ID、名稱、來源、建立時間與關聯項目。 4. 開啟資產確認內容與 metadata。 5. 檢查資料集、模型、報告與模擬的版本依賴。 6. 選擇資產供分析、驗證、模擬或報告使用。 7. 封存或刪除過期資產。 8. 刪除前確認沒有下游流程或報告依賴。' }, en: { purpose: 'Manage datasets, models, reports, simulations, validation experiments, and analysis packages while preserving version, source, and usage traceability.', principle: 'This page does not recalculate models; it manages analysis inputs and result objects. Consistent versions and sources are essential for reproducibility.', formula: 'No new formulas are calculated here; assets retain metrics and methods from their source analysis pages.', interpretation: 'Review asset type, version, status, source, and dependencies. active is usable, archived is retained but not recommended for new work, and unverified means review is incomplete.', limits: 'A list does not prove that content is correct or current. Deleting, archiving, or replacing assets can affect downstream flows, reports, and traceability; metadata is not statistical validation.', recommendation: 'Before use, verify version, source, filters, creation time, and review status. Check dependencies before deletion and retain released versions and required source files.', steps: '1. Open the data-assets page. 2. Filter by type, version, status, or creation time. 3. Review asset ID, name, source, time, and linked items. 4. Open the asset and inspect content and metadata. 5. Check version dependencies among datasets, models, reports, and simulations. 6. Select assets for analysis, validation, simulation, or reporting. 7. Archive or delete obsolete assets. 8. Confirm no downstream flow or report depends on an asset before deletion.' }, 'es-MX': { purpose: 'Gestiona conjuntos de datos, modelos, informes, simulaciones, validaciones y paquetes, conservando versiones, fuentes y trazabilidad.', principle: 'No recalcula modelos; administra entradas y resultados. La coherencia de versiones y fuentes es esencial para reproducibilidad.', formula: 'No calcula fórmulas nuevas; cada activo conserva métricas y métodos de su análisis de origen.', interpretation: 'Revisa tipo, versión, estado, fuente y dependencias. active se puede usar, archived se conserva pero no se recomienda para trabajo nuevo, y unverified indica revisión pendiente.', limits: 'La lista no prueba que el contenido sea correcto o actual. Eliminar, archivar o sustituir puede afectar flujos, informes y trazabilidad; los metadatos no son validación estadística.', recommendation: 'Antes de usar verifica versión, fuente, filtros, fecha y revisión. Comprueba dependencias antes de eliminar y conserva versiones publicadas y fuentes necesarias.', steps: '1. Abre la página de activos. 2. Filtra por tipo, versión, estado o fecha. 3. Revisa ID, nombre, fuente, fecha y enlaces. 4. Abre el activo y consulta contenido y metadatos. 5. Comprueba dependencias entre datos, modelos, informes y simulaciones. 6. Selecciona activos para análisis, validación, simulación o informes. 7. Archiva o elimina activos obsoletos. 8. Confirma que ningún flujo o informe dependa del activo antes de eliminarlo.' } },
  distribution: { 'zh-TW': { purpose: '比較所選欄位的候選分布。', principle: 'AIC／BIC 比較相對配適；KS 檢定檢查一致性。', formula: 'AIC=2k−2ln(L)；BIC=kln(n)−2ln(L)。', interpretation: 'AIC／BIC 越低通常越佳；KS p-value 越大表示本樣本未拒絕。', limits: '樣本配適不代表母體一定服從該分布。', recommendation: '確認參數、圖形與工程合理性後再用於模擬。' }, en: { purpose: 'Compare candidate distributions for the selected column.', principle: 'AIC/BIC compare relative fit; KS checks consistency.', formula: 'AIC=2k−2ln(L); BIC=kln(n)−2ln(L).', interpretation: 'Lower AIC/BIC is usually preferable; a larger KS p-value means the sample does not reject the distribution.', limits: 'A sample fit does not prove the population distribution.', recommendation: 'Check parameters, plots, and engineering plausibility before simulation.' }, 'es-MX': { purpose: 'Compara distribuciones candidatas para la columna seleccionada.', principle: 'AIC/BIC comparan el ajuste; KS verifica consistencia.', formula: 'AIC=2k−2ln(L); BIC=kln(n)−2ln(L).', interpretation: 'Un AIC/BIC menor suele ser preferible; un p-value KS mayor indica que la muestra no rechaza la distribución.', limits: 'El ajuste de una muestra no prueba la distribución poblacional.', recommendation: 'Revisa parámetros, gráficos y plausibilidad antes de simular.' } },
  trend: { 'zh-TW': { purpose: '觀察欄位隨序列的方向、漂移與控制界線狀態。', principle: '以序列差異與連續同向點辨識可能漂移。', formula: '變化量 = 末值 − 首值；控制界線外點需調查。', interpretation: '注意長連續上升／下降、突變與界線外點。', recommendation: '檢查時間排序、單位、校正，並依批次或機台分層。' }, en: { purpose: 'Inspect direction, drift, and control-limit status over sequence order.', principle: 'Sequence differences and same-direction runs indicate possible drift.', formula: 'Change = last value − first value; investigate points beyond limits.', interpretation: 'Watch sustained runs, abrupt shifts, and out-of-limit points.', recommendation: 'Check time order, units, calibration, and segment by batch or machine.' }, 'es-MX': { purpose: 'Observa dirección, deriva y límites de control por orden de secuencia.', principle: 'Las diferencias y rachas en una dirección pueden indicar deriva.', formula: 'Cambio = último − primero; investiga puntos fuera de límites.', interpretation: 'Revisa rachas sostenidas, cambios bruscos y puntos fuera de límite.', recommendation: 'Verifica orden temporal, unidades, calibración y segmenta por lote o máquina.' } },
  timeseries: { 'zh-TW': { purpose: '計算延遲、差分、移動統計與時間序列特徵。', principle: '時間順序與自相關會影響特徵與模型假設。', formula: 'lag_k = x_t−k；差分 = x_t−x_t−1。', interpretation: '檢查缺值、重複時間、間隔不一致與自相關。', recommendation: '先校正時間戳並確認平穩性，再建立預測模型。' }, en: { purpose: 'Compute lags, differences, rolling statistics, and time-series features.', principle: 'Time order and autocorrelation affect features and model assumptions.', formula: 'lag_k = x_t−k; difference = x_t−x_t−1.', interpretation: 'Check missing or duplicate times, irregular intervals, and autocorrelation.', recommendation: 'Correct timestamps and assess stationarity before forecasting.' }, 'es-MX': { purpose: 'Calcula retardos, diferencias, estadísticas móviles y características temporales.', principle: 'El orden temporal y la autocorrelación afectan supuestos y características.', formula: 'lag_k = x_t−k; diferencia = x_t−x_t−1.', interpretation: 'Revisa tiempos faltantes o duplicados, intervalos irregulares y autocorrelación.', recommendation: 'Corrige marcas de tiempo y evalúa estacionariedad antes de pronosticar.' } },
  grr: { 'zh-TW': { purpose: '評估量測系統的重複性與再現性。', principle: '將量具與操作者變異和零件間變異分離。', formula: '%GRR = GRR變異／總變異 × 100%。', interpretation: '低%GRR較佳；邊界結果須依應用重要性判斷。', recommendation: '優先改善量具固定、校正與操作一致性後重新量測。' }, en: { purpose: 'Evaluate repeatability and reproducibility of the measurement system.', principle: 'Separate equipment and operator variation from part-to-part variation.', formula: '%GRR = GRR variation / total variation × 100%.', interpretation: 'Lower %GRR is better; judge marginal results by application criticality.', recommendation: 'Improve fixture stability, calibration, and operator consistency, then remeasure.' }, 'es-MX': { purpose: 'Evalúa repetibilidad y reproducibilidad del sistema de medición.', principle: 'Separa variación del equipo y operador de la variación pieza a pieza.', formula: '%GRR = variación GRR / variación total × 100%.', interpretation: 'Un %GRR menor es mejor; juzga resultados marginales según criticidad.', recommendation: 'Mejora fijación, calibración y consistencia del operador y vuelve a medir.' } },
  spc: { 'zh-TW': { purpose: '使用 I-MR、X̄-R、X̄-S、P、NP、C、U、EWMA、CUSUM 等控制圖，監控製程穩定性、變異與特殊原因。', principle: '控制圖以時間或樣本順序監控製程統計穩定性；控制界線反映共同原因變異，界線外點或規則違反可能表示特殊原因，圖型須依資料型態與子群結構選擇。', formula: '一般控制界線=中心線±3σ；Cp=(USL−LSL)／(6σ)；Cpk=min[(USL−μ)／(3σ),(μ−LSL)／(3σ)]；I-MR 以個別值與移動全距估計變異。', interpretation: '控制界線判斷統計穩定性，規格限判斷工程符合性，兩者不可混用。注意界線外點、長串同側、連續上升／下降、週期性與變異突然改變；EWMA／CUSUM 對小幅持續漂移較敏感。', limits: '界線依資料與估計方法而定；時間未排序、子群錯誤、量測不穩定或製程改變都可能造成誤判。控制圖不代表因果，也不能取代工程調查。', recommendation: '先確認時間戳、量測系統、子群定義與圖型，再調查異常點。不要未確認原因就刪除資料或重算界線；處理特殊原因後保留前後版本並重新評估能力。', steps: '1. 確認資料集、欄位角色與時間順序。 2. 依資料型態與子群選擇控制圖。 3. 選擇量測欄位與子群設定。 4. 確認中心線、UCL／LCL、LSL／USL 與目標值。 5. 執行 SPC 分析。 6. 檢查界線外點與 Western Electric／Nelson 規則。 7. 查看平均值、變異與 Cp／Cpk 或 Pp／Ppk。 8. 調查特殊原因並記錄處置。 9. 確認後儲存 SPC 分析與報告。' }, en: { purpose: 'Use I-MR, X-bar-R, X-bar-S, P, NP, C, U, EWMA, and CUSUM charts to monitor stability, variation, and special causes.', principle: 'Charts monitor statistical stability over time or sample order. Control limits reflect common-cause variation; out-of-limit points or rule violations may indicate special causes. Select the chart by data type and subgroup structure.', formula: 'General limits=center line±3σ; Cp=(USL−LSL)/(6σ); Cpk=min[(USL−μ)/(3σ),(μ−LSL)/(3σ)]; I-MR estimates variation from individuals and moving ranges.', interpretation: 'Control limits assess stability; specification limits assess engineering conformance and must not be mixed. Watch out-of-limit points, long runs on one side, sustained trends, cycles, and sudden variation changes; EWMA/CUSUM are sensitive to small persistent drift.', limits: 'Limits depend on data and estimation. Unsorted time, wrong subgroups, unstable measurement, or process changes can mislead. Charts do not prove causality or replace investigation.', recommendation: 'Verify timestamps, measurement system, subgroups, and chart type before investigating. Do not delete data or recalculate limits before confirming causes; retain before/after versions and reassess capability.', steps: '1. Confirm dataset, field roles, and time order. 2. Select a chart by data type and subgroup. 3. Choose measurement field and subgroup settings. 4. Confirm center line, UCL/LCL, LSL/USL, and target. 5. Run SPC. 6. Review out-of-limit points and Western Electric/Nelson rules. 7. Review mean, variation, and Cp/Cpk or Pp/Ppk. 8. Investigate and record special causes. 9. Save the SPC analysis and report after review.' }, 'es-MX': { purpose: 'Usa gráficos I-MR, X̄-R, X̄-S, P, NP, C, U, EWMA y CUSUM para vigilar estabilidad, variación y causas especiales.', principle: 'Los gráficos vigilan estabilidad por tiempo u orden. Los límites reflejan causas comunes; puntos fuera o reglas violadas pueden indicar causas especiales. Elige según tipo de datos y subgrupos.', formula: 'Límites generales=línea central±3σ; Cp=(USL−LSL)/(6σ); Cpk=min[(USL−μ)/(3σ),(μ−LSL)/(3σ)]; I-MR estima variación con individuales y rangos móviles.', interpretation: 'Límites de control evalúan estabilidad; límites de especificación evalúan conformidad y no se intercambian. Observa puntos fuera, rachas, tendencias, ciclos y cambios bruscos; EWMA/CUSUM detectan deriva persistente pequeña.', limits: 'Dependen de datos y estimación; tiempos desordenados, subgrupos erróneos, medición inestable o cambios de proceso pueden sesgar. No prueban causalidad ni sustituyen investigación.', recommendation: 'Verifica tiempos, medición, subgrupos y gráfico antes de investigar. No borres datos ni recalcules límites sin confirmar causas; conserva versiones y reevalúa capacidad.', steps: '1. Confirma datos, roles y orden temporal. 2. Elige gráfico según datos y subgrupo. 3. Selecciona medición y subgrupo. 4. Confirma línea central, UCL/LCL, LSL/USL y objetivo. 5. Ejecuta SPC. 6. Revisa puntos fuera y reglas Western Electric/Nelson. 7. Revisa media, variación y Cp/Cpk o Pp/Ppk. 8. Investiga y registra causas especiales. 9. Guarda análisis e informe.' } },
  modelCenter: { 'zh-TW': { purpose: '比較 DOE 線性、DOE 二次及其他模型的配適、驗證、殘差診斷、交互作用、SHAP 可解釋性、敏感度與效應量，選出適合預測、模擬與驗證實驗的模型。', principle: '迴歸模型估計輸入對輸出的關係；ANOVA 評估主效應與交互作用；殘差診斷檢查模型假設；SHAP 與 Permutation RMSE 衡量變數貢獻；標準化效應量衡量實際影響大小。', formula: 'RMSE=√[Σ(yᵢ−ŷᵢ)²／n]；R²=1−SSE／SST；AIC=2k−2ln(L)；BIC=kln(n)−2ln(L)；標準化效應量=βⱼ×SD(xⱼ)／SD(y)。', interpretation: '較低 RMSE、AIC／BIC 通常較佳，但需搭配驗證結果。殘差應大致隨機；高 VIF 表示多重共線性風險；交互作用圖的斜率差異表示可能存在交互影響；SHAP、敏感度與效應量排名應與工程知識交叉確認。', limits: '模型結果描述目前樣本與輸入範圍，不代表母體或因果關係；高配適度不一定代表外部資料表現良好，共線性、樣本不足、外推與資料洩漏都可能使結論失真。', recommendation: '先確認資料品質、規格與輸入範圍，再比較模型驗證指標與診斷結果。若存在高 VIF、殘差自相關或明顯外推，先改善資料或設計驗證實驗。', steps: '1. 選擇資料集、輸出欄位與輸入欄位。 2. 選擇模型類型並執行配適。 3. 檢查 R²、調整後 R²、RMSE、AIC／BIC 與模型狀態。 4. 查看殘差、常態性、自相關與多重共線性診斷。 5. 檢查主效應、交互作用、SHAP、敏感度與效應量。 6. 比較候選模型的預測與驗證表現。 7. 確認適用範圍與輸入操作範圍。 8. 儲存模型版本後交由模擬、驗證實驗或報告流程使用。' }, en: { purpose: 'Compare DOE linear, DOE quadratic, and other models by fit, validation, residual diagnostics, interactions, SHAP explainability, sensitivity, and effect size for prediction, simulation, and validation experiments.', principle: 'Regression estimates input-output relationships; ANOVA evaluates main and interaction effects; residual diagnostics check assumptions; SHAP and permutation RMSE measure contribution; standardized effect size measures practical impact.', formula: 'RMSE=√[Σ(yᵢ−ŷᵢ)²/n]; R²=1−SSE/SST; AIC=2k−2ln(L); BIC=kln(n)−2ln(L); standardized effect=βⱼ×SD(xⱼ)/SD(y).', interpretation: 'Lower RMSE and AIC/BIC are usually preferable but must be paired with validation. Residuals should be broadly random; high VIF signals multicollinearity; differing interaction slopes indicate possible interaction. Cross-check SHAP, sensitivity, and effect-size rankings with engineering knowledge.', limits: 'Results describe the current sample and input range, not population or causality. High fit does not guarantee external performance; collinearity, small samples, extrapolation, and leakage can distort conclusions.', recommendation: 'Verify data quality, specifications, and input ranges before comparing validation and diagnostics. Address high VIF, residual autocorrelation, or extrapolation with better data or a validation experiment.', steps: '1. Select dataset, output, and input fields. 2. Choose a model type and fit it. 3. Review R², adjusted R², RMSE, AIC/BIC, and status. 4. Check residual, normality, autocorrelation, and multicollinearity diagnostics. 5. Review main effects, interactions, SHAP, sensitivity, and effect size. 6. Compare prediction and validation performance. 7. Confirm applicability and operating ranges. 8. Save the model version for simulation, validation, or reporting.' }, 'es-MX': { purpose: 'Compara modelos DOE lineal, DOE cuadrático y otros por ajuste, validación, residuos, interacciones, explicabilidad SHAP, sensibilidad y tamaño de efecto para predicción, simulación y experimentos.', principle: 'La regresión estima relaciones entrada-salida; ANOVA evalúa efectos principales e interacciones; los residuos revisan supuestos; SHAP y RMSE por permutación miden contribución; el efecto estandarizado mide impacto práctico.', formula: 'RMSE=√[Σ(yᵢ−ŷᵢ)²/n]; R²=1−SSE/SST; AIC=2k−2ln(L); BIC=kln(n)−2ln(L); efecto estandarizado=βⱼ×SD(xⱼ)/SD(y).', interpretation: 'Un RMSE y AIC/BIC menor suele ser preferible junto con validación. Los residuos deben ser aleatorios; VIF alto indica multicolinealidad; pendientes distintas sugieren interacción. Contrasta rankings SHAP, sensibilidad y efecto con ingeniería.', limits: 'Los resultados describen la muestra y rango actuales, no población ni causalidad. Un ajuste alto no garantiza desempeño externo; colinealidad, muestras pequeñas, extrapolación y fuga pueden distorsionar.', recommendation: 'Verifica calidad, especificaciones y rangos antes de comparar métricas. Corrige VIF alto, autocorrelación residual o extrapolación mediante mejores datos o un experimento de validación.', steps: '1. Selecciona conjunto, salida y entradas. 2. Elige y ajusta el modelo. 3. Revisa R², R² ajustado, RMSE, AIC/BIC y estado. 4. Revisa residuos, normalidad, autocorrelación y multicolinealidad. 5. Consulta efectos principales, interacciones, SHAP, sensibilidad y tamaño de efecto. 6. Compara predicción y validación. 7. Confirma aplicabilidad y rangos operativos. 8. Guarda la versión para simulación, validación o informes.' } },
  monteCarlo: { 'zh-TW': { purpose: '依輸入欄位的指定分布與參數抽樣，代入模型並將輸出與 LSL、USL、中心值比較，估計 NG 機率、輸出分布與預測能力。', principle: '從輸入分布重複抽樣並代入模型，使用大量試驗近似輸出分布與超規格機率；存在相關性時以聯合抽樣或 Copula 保留相依結構。', formula: 'NG 機率=NG 次數／總次數×100%；合格率=合格次數／總次數×100%；Pp=(USL−LSL)／(6σoverall)；Ppk=min[(USL−μ)／(3σoverall),(μ−LSL)／(3σoverall)]。', interpretation: '直方圖與 CDF 顯示輸出相對於規格與中心值的位置；分布偏移表示中心化問題，分布過寬表示變異過大。p1、p5、p50、p95、p99 可協助判讀尾端風險，並應查看 NG 方向與超出幅度。', limits: '結果依賴輸入分布、參數、模型、相關性、規格與種子；模擬不等於實際生產，也不能證明因果。輸入超出訓練範圍時，輸出屬外推。', recommendation: '以資料健檢的 best_distribution 作為起始設定，檢查參數與工程合理性；比較 Bootstrap、指定分布與相關性情境，固定種子以重現結果。高 NG 時先區分規格、中心偏移、輸入變異與外推風險。', steps: '1. 確認資料集與模型版本已載入。 2. 選擇模型、模擬次數與隨機種子。 3. 檢查每個 input 的抽樣方式、分布與參數。 4. 確認 Bootstrap、指定分布或 Copula 聯合抽樣設定。 5. 設定 LSL／USL、中心值與異常情境。 6. 執行模擬。 7. 檢查 NG 次數、平均值、中位數、標準差、百分位數、Pp／Ppk 與圖表。 8. 比較模型或分布情境，儲存結果並產生報告。' }, en: { purpose: 'Sample each input using its selected distribution and parameters, run the model, and compare outputs with LSL, USL, and center value to estimate NG risk, output distribution, and capability.', principle: 'Repeatedly sample inputs and evaluate the model to approximate output risk; use joint sampling or a copula to preserve dependence when inputs are correlated.', formula: 'NG probability=NG count/total×100%; yield=pass count/total×100%; Pp=(USL−LSL)/(6σoverall); Ppk=min[(USL−μ)/(3σoverall),(μ−LSL)/(3σoverall)].', interpretation: 'Use the histogram and CDF to locate outputs relative to limits and center. A shifted distribution suggests centering risk; a wide distribution suggests excess variation. Review p1, p5, p50, p95, p99, NG direction, and exceedance magnitude.', limits: 'Results depend on distributions, parameters, model, dependence, specifications, and seed. Simulation is not production evidence or causal proof. Inputs outside training range produce extrapolated outputs.', recommendation: 'Start with the data-check best_distribution and verify parameters and engineering plausibility. Compare bootstrap, specified distributions, and dependence scenarios; fix the seed for reproducibility. When NG is high, separate specification, centering, variation, and extrapolation causes.', steps: '1. Confirm dataset and model version. 2. Choose model, simulation count, and seed. 3. Review each input sampling method, distribution, and parameters. 4. Confirm bootstrap, specified, or copula joint sampling. 5. Set LSL/USL, center, and anomaly scenarios. 6. Run simulation. 7. Review NG count, mean, median, standard deviation, percentiles, Pp/Ppk, and charts. 8. Compare model or distribution scenarios and save the result or report.' }, 'es-MX': { purpose: 'Muestrea cada entrada con su distribución y parámetros, ejecuta el modelo y compara la salida con LSL, USL y centro para estimar riesgo NG, distribución y capacidad.', principle: 'Repite muestreos y evaluaciones para aproximar el riesgo; usa muestreo conjunto o cópula para conservar dependencias entre entradas correlacionadas.', formula: 'Probabilidad NG=conteo NG/total×100%; rendimiento=conteo conforme/total×100%; Pp=(USL−LSL)/(6σoverall); Ppk=min[(USL−μ)/(3σoverall),(μ−LSL)/(3σoverall)].', interpretation: 'Usa histograma y CDF respecto a límites y centro. Un desplazamiento indica riesgo de centrado y una distribución ancha, exceso de variación. Revisa p1, p5, p50, p95, p99, dirección y magnitud fuera de límite.', limits: 'Depende de distribuciones, parámetros, modelo, dependencia, especificaciones y semilla. No equivale a evidencia de producción ni prueba causal. Fuera del rango de entrenamiento es extrapolación.', recommendation: 'Inicia con best_distribution de la revisión de datos y valida parámetros y plausibilidad. Compara bootstrap, distribuciones especificadas y dependencias; fija semilla para reproducibilidad. Con NG alto separa límites, centrado, variación y extrapolación.', steps: '1. Confirma conjunto y versión del modelo. 2. Elige modelo, número de simulaciones y semilla. 3. Revisa método, distribución y parámetros de cada entrada. 4. Confirma bootstrap, distribución especificada o cópula. 5. Configura LSL/USL, centro y anomalías. 6. Ejecuta la simulación. 7. Revisa conteo NG, media, mediana, desviación, percentiles, Pp/Ppk y gráficos. 8. Compara escenarios y guarda resultado o informe.' } },
  validation: { 'zh-TW': { purpose: '比較候選模型在驗證資料上的表現，評估預測可靠性，並規劃可在實際製程執行的後續實驗。', principle: '以保留資料或新實驗資料評估模型泛化能力，透過預測與實測誤差比較可靠性，並以重複實驗估計純誤差與結果穩定性。', formula: 'RMSE=√[Σ(yᵢ−ŷᵢ)²／n]；MAE=Σ|yᵢ−ŷᵢ|／n；R²=1−SSE／SST；預測誤差 eᵢ=yᵢ−ŷᵢ。', interpretation: '較低 RMSE／MAE、較高驗證 R² 通常較佳。預測與實測應接近一致；誤差集中偏正或偏負表示可能存在系統性偏差。超出模型範圍的條件屬外推，不宜直接採信。', limits: '結果取決於驗證資料與實驗設計，不能保證所有製程條件都成立。沒有實際新實驗時，只能算資料重抽樣或保留資料驗證，不能視為因果證明。', recommendation: '優先選擇涵蓋實際製程範圍、風險可控且能區分候選模型的條件；執行前確認規格、操作上下限、量測系統與安全條件，完成後將實測結果回填並更新模型。', steps: '1. 確認資料集、模型版本與輸出欄位已載入。 2. 執行完整驗證，比較各模型的 RMSE、R²、預測誤差與狀態。 3. 檢查模型輸入範圍、輸出規格與實際製程條件。 4. 查看下一步實驗條件與推薦因素。 5. 確認重複次數、新因素與實驗範圍。 6. 檢查是否超出安全或模型適用範圍。 7. 執行或匯出實驗計畫並記錄量測結果。 8. 回填實測值，比較預測與實測差異。 9. 確認結果後儲存實驗與模型版本。' }, en: { purpose: 'Compare candidate models on validation data, assess prediction reliability, and plan follow-up experiments that can be run in the real process.', principle: 'Use holdout or new experiment data to assess generalization, compare predicted and measured errors, and use replicates to estimate pure error and stability.', formula: 'RMSE=√[Σ(yᵢ−ŷᵢ)²/n]; MAE=Σ|yᵢ−ŷᵢ|/n; R²=1−SSE/SST; prediction error eᵢ=yᵢ−ŷᵢ.', interpretation: 'Lower RMSE/MAE and higher validation R² are usually preferable. Predictions should align with measurements; errors biased positive or negative may indicate systematic bias. Conditions outside the model range are extrapolation and require caution.', limits: 'Results depend on validation data and design and do not guarantee all process conditions. Without new physical experiments, this is holdout or resampling validation, not causal proof.', recommendation: 'Choose conditions that cover the real process, remain safe, and distinguish candidates. Before execution verify specifications, operating limits, measurement system, and safety; feed measured results back into the next model version.', steps: '1. Confirm dataset, model version, and output are loaded. 2. Run full validation and compare RMSE, R², errors, and status. 3. Check model input range, output specifications, and process conditions. 4. Review next-experiment conditions and recommended factors. 5. Confirm replicates, new factors, and ranges. 6. Check safety and applicability limits. 7. Run or export the plan and record measurements. 8. Enter measured values and compare predictions with measurements. 9. Save the experiment and model version after review.' }, 'es-MX': { purpose: 'Compara modelos candidatos con datos de validación, evalúa la fiabilidad predictiva y planifica experimentos ejecutables en el proceso real.', principle: 'Usa datos retenidos o nuevos experimentos para evaluar generalización, compara predicciones con mediciones y usa réplicas para estimar error puro y estabilidad.', formula: 'RMSE=√[Σ(yᵢ−ŷᵢ)²/n]; MAE=Σ|yᵢ−ŷᵢ|/n; R²=1−SSE/SST; error eᵢ=yᵢ−ŷᵢ.', interpretation: 'RMSE/MAE menor y R² de validación mayor suelen ser mejores. Predicciones y mediciones deben alinearse; sesgo positivo o negativo puede indicar error sistemático. Fuera del rango del modelo es extrapolación.', limits: 'Depende de datos y diseño de validación y no garantiza todas las condiciones. Sin experimentos físicos nuevos, es validación retenida o por remuestreo, no prueba causal.', recommendation: 'Elige condiciones que cubran el proceso real, sean seguras y distingan modelos. Verifica especificaciones, límites, sistema de medición y seguridad; incorpora las mediciones a la siguiente versión.', steps: '1. Confirma datos, versión del modelo y salida cargados. 2. Ejecuta validación completa y compara RMSE, R², errores y estado. 3. Revisa rango del modelo, especificaciones y condiciones reales. 4. Consulta condiciones y factores recomendados. 5. Confirma réplicas, factores nuevos y rangos. 6. Revisa límites de seguridad y aplicabilidad. 7. Ejecuta o exporta el plan y registra mediciones. 8. Introduce valores medidos y compara predicción con medición. 9. Guarda experimento y versión del modelo.' } },
  reports: { 'zh-TW': { purpose: '產生 HTML、PDF、Excel 等可追溯分析報告，並管理資料集、模型、模擬、驗證實驗與報告版本。', principle: '本頁不重新計算統計模型，而是保存並呈現各分析模組的結果；報告結論有效性取決於來源資料、模型假設與驗證狀態。', formula: '本頁不產生新的統計公式；報告沿用分布配適、SPC、模型配適、敏感度、模擬與驗證頁面的指標。', interpretation: '確認報告中的圖表、欄位、篩選條件、規格界線與模型版本一致。若報告與目前頁面不同，先檢查產生時間與來源版本。', limits: '報告是特定資料、模型與設定下的快照，不代表最新狀態或母體結論；不同格式可能有排版或內容差異。刪除報告可能影響後續追溯。', recommendation: '分享或發布前檢查 metadata、資料集版本、模型版本、篩選條件、證據狀態與驗證紀錄，並保留可重現的來源資料與設定。', steps: '1. 確認資料集、模型與分析結果已儲存。 2. 選擇報告類型與內容。 3. 產生報告並確認輸出位置。 4. 檢查圖表、指標、規格、限制與建議。 5. 檢查 metadata，包括資料集、模型、篩選條件、分析時間與版本。 6. 使用「開啟」檢視報告，必要時重新產生其他格式。 7. 刪除不需要的報告紀錄。 8. 分享前確認資料、模型與報告版本可相互追溯。' }, en: { purpose: 'Generate traceable HTML, PDF, and Excel reports and manage versions of datasets, models, simulations, validation experiments, and reports.', principle: 'This page does not recalculate models; it preserves and presents module results. Validity depends on source data, assumptions, and validation status.', formula: 'No new formulas are calculated here; reports reuse metrics from distribution fitting, SPC, modeling, sensitivity, simulation, and validation.', interpretation: 'Check that report charts, fields, filters, specification limits, and model versions match the current page. If they differ, inspect report time and source versions.', limits: 'A report is a snapshot of specific data, model, and settings, not necessarily the latest state or a population conclusion. Formats may differ in layout or presentation; deleting can affect traceability.', recommendation: 'Before sharing or release, check metadata, dataset/model versions, filters, evidence status, and validation records, and retain reproducible source data and settings.', steps: '1. Confirm dataset, model, and analysis results are saved. 2. Choose report format and content. 3. Generate the report and confirm its output location. 4. Review charts, metrics, specifications, limitations, and recommendations. 5. Check metadata: dataset, model, filters, analysis time, and version. 6. Open the report and regenerate another format if needed. 7. Delete obsolete report records. 8. Confirm cross-version traceability before sharing.' }, 'es-MX': { purpose: 'Genera informes HTML, PDF y Excel trazables y gestiona versiones de datos, modelos, simulaciones, validaciones e informes.', principle: 'No recalcula modelos; conserva y presenta resultados de módulos. La validez depende de datos, supuestos y estado de validación.', formula: 'No calcula fórmulas nuevas; reutiliza métricas de distribuciones, SPC, modelos, sensibilidad, simulación y validación.', interpretation: 'Comprueba que gráficos, campos, filtros, límites y versiones coincidan con la página actual. Si difieren, revisa hora y versiones de origen.', limits: 'El informe es una instantánea de datos, modelo y ajustes concretos, no necesariamente el estado actual ni una conclusión poblacional. Los formatos pueden variar; eliminar afecta trazabilidad.', recommendation: 'Antes de compartir, revisa metadatos, versiones, filtros, estado de evidencia y validaciones; conserva datos y ajustes reproducibles.', steps: '1. Confirma que datos, modelo y resultados estén guardados. 2. Elige formato y contenido. 3. Genera el informe y confirma ubicación. 4. Revisa gráficos, métricas, especificaciones, límites y recomendaciones. 5. Comprueba metadatos: datos, modelo, filtros, hora y versión. 6. Abre el informe y genera otro formato si es necesario. 7. Elimina registros obsoletos. 8. Confirma trazabilidad entre versiones antes de compartir.' } },
  settings: { 'zh-TW': { purpose: '管理介面語言、AI 提供者與模型、資料與輸出路徑，以及影響專案執行與結果保存的系統選項。', principle: '系統設定本身不執行統計計算，而是提供分析模組所需的語言、模型服務、儲存位置與執行環境。', formula: '本頁不產生統計公式；連線測試、設定儲存與路徑檢查屬於系統功能驗證。', interpretation: '已啟用表示功能開啟；連線成功表示目前設定可連接提供者；未就緒通常表示服務、模型、金鑰或網路尚不可用。儲存後重新進入仍保留設定，才表示持久化成功。', limits: '連線成功不代表模型回覆一定正確。設定變更可能只影響新請求；API 金鑰與敏感設定不應寫入報告或公開紀錄。', recommendation: '正式使用前測試連線、確認端點與模型名稱、檢查持久化，並依資料敏感度選擇去敏或本機處理。', steps: '1. 選擇介面語言。 2. 設定 AI 提供者、伺服器位址、API 金鑰與模型。 3. 測試連線並確認狀態。 4. 設定資料、報告與匯出路徑。 5. 儲存設定並重新載入確認持久化。 6. 重新啟動程式後再次檢查。 7. 若未生效，檢查權限、路徑、環境變數與服務狀態。' }, en: { purpose: 'Manage interface language, AI provider and model, data and output paths, and system options that affect execution and persistence.', principle: 'Settings do not perform statistical calculations; they provide language, model service, storage, and runtime configuration.', formula: 'No statistical formulas are calculated here; connection tests, saving, and path checks validate system configuration.', interpretation: 'Enabled means the feature is on; connection success means the provider is reachable; not ready may indicate service, model, key, or network issues. Persistence is confirmed when settings remain after reload.', limits: 'A successful connection does not guarantee correct model responses. Changes may affect only new requests; API keys and sensitive settings must not enter reports or public records.', recommendation: 'Test the connection, endpoint, and model, verify persistence, and choose de-identification or local processing based on data sensitivity.', steps: '1. Select interface language. 2. Set AI provider, server URL, API key, and model. 3. Test the connection and review status. 4. Set data, report, and export paths. 5. Save and reload to verify persistence. 6. Restart the app and check again. 7. If not applied, check permissions, paths, environment variables, and service status.' }, 'es-MX': { purpose: 'Gestiona idioma, proveedor y modelo de IA, rutas de datos y salida, y opciones que afectan ejecución y persistencia.', principle: 'La configuración no calcula estadísticas; proporciona idioma, servicio de modelo, almacenamiento y entorno.', formula: 'No calcula fórmulas estadísticas; prueba conexiones, guardado y rutas del sistema.', interpretation: 'Habilitado indica función activa; conexión exitosa indica proveedor accesible; no listo puede deberse a servicio, modelo, clave o red. La persistencia se confirma tras recargar.', limits: 'Conectar no garantiza respuestas correctas. Los cambios pueden afectar solo solicitudes nuevas; las claves y datos sensibles no deben entrar en informes públicos.', recommendation: 'Prueba conexión, endpoint y modelo, verifica persistencia y elige desidentificación o procesamiento local según sensibilidad.', steps: '1. Elige idioma. 2. Configura proveedor, URL, clave y modelo. 3. Prueba conexión y estado. 4. Configura rutas de datos, informes y exportación. 5. Guarda y recarga para verificar persistencia. 6. Reinicia y comprueba. 7. Si falla, revisa permisos, rutas, variables y servicio.' } },
}
export function getGuideSection(tab: string, subtab: string | undefined, language: string): GuideSection {
  const normalized = language.toLowerCase().startsWith('zh') ? 'zh-TW' : language.toLowerCase().startsWith('es') ? 'es-MX' : 'en'
  const lang = normalized as keyof typeof common
  const base = { ...common[lang], title: '' }
  const topicKey = tab === 'exploration' ? (subtab || 'distribution') : tab
  const topic = topics[topicKey]?.[lang] ?? topics[topicKey]?.en
  const distributionSteps = lang === 'zh-TW'
    ? '1. 選擇要分析的 input 或 output 欄位。 2. 按「分布適配」。 3. 檢查樣本數、範圍、平均值與標準差。 4. 比較直方圖、密度圖與 CDF。 5. 比較候選分布的 AIC、BIC、KS p-value。 6. 查看 loc、scale、shape 等配適參數。 7. 確認工程合理性後，才將最佳分布供蒙地卡羅或模型配適使用。 8. 若結果異常，回資料匯入檢查缺值、離群值、單位與樣本量。'
    : lang === 'es-MX'
      ? '1. Selecciona una columna de entrada o salida. 2. Pulsa «Ajustar distribución». 3. Revisa n, rango, media y desviación. 4. Compara histograma, densidad y CDF. 5. Compara AIC, BIC y p-value KS. 6. Revisa parámetros loc, scale y shape. 7. Usa la distribución en Monte Carlo o modelos solo tras validar su plausibilidad. 8. Si es anómala, revisa faltantes, atípicos, unidades y tamaño de muestra en Importación.'
      : '1. Select an input or output column. 2. Click “Fit distribution”. 3. Check n, range, mean, and standard deviation. 4. Compare histogram, density, and CDF. 5. Compare candidate AIC, BIC, and KS p-values. 6. Review loc, scale, and shape parameters. 7. Use the distribution for Monte Carlo or modeling only after engineering review. 8. If unexpected, check missing values, outliers, units, and sample size in Data Import.'
  const trendSteps = lang === 'zh-TW'
    ? '1. 選擇要分析的 input 或 output 欄位。 2. 按「繪製趨勢」。 3. 確認資料列或時間戳排序正確。 4. 讀取首值、末值、變化量與方向。 5. 比較 UCL／LCL；若是 output，再查看 LSL／USL。 6. 標記連續同向點、突變、漂移與界線外點。 7. 回查時間戳、單位、校正、批次與機台後再採取行動。'
    : lang === 'es-MX'
      ? '1. Selecciona una entrada o salida. 2. Pulsa «Dibujar tendencia». 3. Confirma el orden de filas o marcas de tiempo. 4. Revisa primer valor, último, cambio y dirección. 5. Compara UCL/LCL y, para salidas, LSL/USL. 6. Identifica rachas, cambios bruscos, deriva y puntos fuera de límite. 7. Revisa tiempos, unidades, calibración, lote y máquina antes de actuar.'
      : '1. Select an input or output column. 2. Click “Draw trend”. 3. Confirm row or timestamp ordering. 4. Read first, last, change, and direction. 5. Compare UCL/LCL and, for outputs, LSL/USL. 6. Identify runs, abrupt shifts, drift, and out-of-limit points. 7. Check timestamps, units, calibration, batch, and machine before acting.'
  const timeseriesSteps = lang === 'zh-TW'
    ? '1. 選擇時間欄位與要分析的 input 或 output 數值欄位。 2. 設定移動視窗（例如 3、5、10）。 3. 按「計算特徵」。 4. 檢查 lag、差分、移動平均、移動標準差與 drift。 5. 確認時間格式、時區、排序與間隔一致。 6. 處理缺值與重複時間。 7. 建模前檢查平穩性與自相關，並避免使用未來資料造成洩漏。'
    : lang === 'es-MX'
      ? '1. Selecciona columna de tiempo y una entrada o salida numérica. 2. Configura ventanas móviles (por ejemplo 3, 5 y 10). 3. Pulsa «Calcular características». 4. Revisa retardos, diferencias, medias, desviaciones móviles y deriva. 5. Confirma formato, zona horaria, orden e intervalos. 6. Trata faltantes y tiempos duplicados. 7. Evalúa estacionariedad y autocorrelación y evita usar datos futuros al modelar.'
      : '1. Select a time column and an input or output numeric column. 2. Set rolling windows (for example 3, 5, and 10). 3. Click “Compute features”. 4. Review lags, differences, rolling mean, rolling standard deviation, and drift. 5. Confirm timestamp format, timezone, ordering, and interval consistency. 6. Handle missing and duplicate times. 7. Assess stationarity and autocorrelation before modeling and prevent future-data leakage.'
  const grrSteps = lang === 'zh-TW'
    ? '1. 選擇測量欄位、零件欄位與操作者欄位。 2. 確認零件數、操作者數與每件重複次數。 3. 按「執行 GRR 分析」。 4. 查看 %GRR、%Part、GRR、EV 與 AV。 5. 依 <10%、10–30%、>30% 判定區間評估。 6. 根據主導變異改善治具、校正或操作方法。 7. 重新量測確認改善效果。'
    : lang === 'es-MX'
      ? '1. Selecciona columnas de medición, pieza y operador. 2. Confirma número de piezas, operadores y repeticiones. 3. Pulsa «Ejecutar GRR». 4. Revisa %GRR, %Part, GRR, EV y AV. 5. Evalúa los rangos <10%, 10–30% y >30%. 6. Mejora fijación, calibración o método según la variación dominante. 7. Vuelve a medir para confirmar.'
      : '1. Select measurement, part, and operator columns. 2. Confirm part count, operator count, and repeats. 3. Click “Run GRR”. 4. Review %GRR, %Part, GRR, EV, and AV. 5. Evaluate the <10%, 10–30%, and >30% bands. 6. Improve fixture, calibration, or method based on the dominant variation. 7. Remeasure to confirm improvement.'
  const dataImportNotes = topicKey === 'dataImport' ? (lang === 'zh-TW'
    ? { interpretation: '資料契約：一般 CSV 範本提供 datetime、input_*、output_thickness、result 及可選的 lot／machine／operator／part，適用一般分析、DOE、分布、趨勢、時間序列、SPC 與蒙地卡羅；工程多層級範本增加 measurement_id、product_id、lot_id、station_id、process_step、subgroup_id，適合 GRR 與階層資料。', recommendation: '使用者收集資料時先選對範本：一般分析使用一般 CSV，GRR 或多批次／多站點資料使用工程多層級範本。測試情境檔案是內部驗證資料，不必提供給使用者下載。' }
    : lang === 'es-MX'
      ? { interpretation: 'Contrato de datos: la plantilla CSV general incluye datetime, input_*, output_thickness, result y lot/machine/operator/part opcionales para análisis, DOE, series temporales, SPC y Monte Carlo; la plantilla de ingeniería añade IDs de medición, producto, lote, estación, paso y subgrupo para GRR y datos jerárquicos.', recommendation: 'Elige la plantilla correcta: CSV general para análisis habituales y plantilla de ingeniería para GRR o datos por lote/estación. Los archivos de escenarios son datos internos de prueba y no deben confundirse con plantillas de usuario.' }
      : { interpretation: 'Data contract: the general CSV template includes datetime, input_*, output_thickness, result, and optional lot/machine/operator/part for analysis, DOE, time series, SPC, and Monte Carlo; the engineering template adds measurement, product, lot, station, process-step, and subgroup IDs for GRR and hierarchical data.', recommendation: 'Choose the right template: general CSV for standard analysis, engineering template for GRR or lot/station hierarchies. Scenario fixtures are internal test data and are not user-download templates.' }) : {}
  const distributionNotes = topicKey === 'distribution' ? (lang === 'zh-TW'
    ? { interpretation: 'AIC／BIC 越低通常越佳，但只能在同一資料與候選集合內比較；KS p-value 較大表示樣本未拒絕該分布，不代表已證明正確。配適參數必須落在資料範圍與工程意義內。', recommendation: '若最佳分布合理且候選差異明顯，可作為蒙地卡羅起始分布；若差異小或 KS 不佳，請保留多個情境並回查資料品質。' }
    : lang === 'es-MX'
      ? { interpretation: 'Un AIC/BIC menor suele ser mejor solo dentro del mismo conjunto de candidatos; un p-value KS mayor indica que la muestra no rechaza la distribución, no que esté probada. Valida los parámetros contra el rango y el proceso.', recommendation: 'Usa la distribución como inicio de Monte Carlo solo si es plausible; si las diferencias son pequeñas, conserva escenarios alternativos y revisa la calidad de datos.' }
      : { interpretation: 'Lower AIC/BIC is preferable only within the same candidate set; a larger KS p-value means the sample does not reject the distribution, not that it is proven. Validate parameters against the data range and process meaning.', recommendation: 'Use it as a Monte Carlo starting distribution only when plausible; if candidates are close, retain alternatives and recheck data quality.' }) : {}
  const trendNotes = topicKey === 'trend' ? (lang === 'zh-TW'
    ? { principle: '控制界線用於判斷統計穩定性；規格限用於判斷是否符合工程要求，兩者不可混用。首末值只能描述端點，需搭配連續點與變化量。', formula: '變化量 = 末值 − 首值；界線外點數 = 超過 UCL 或低於 LCL 的點數。', interpretation: '連續同向點可能表示漂移，突變可能表示換批、設定變更或量測問題；界線外點應先調查特殊原因。', recommendation: '先確認資料排序與量測品質，再按批次／機台分層比較；不要僅憑趨勢宣稱因果。' }
    : lang === 'es-MX'
      ? { principle: 'Los límites de control evalúan estabilidad estadística; los de especificación evalúan requisitos. No son intercambiables.', formula: 'Cambio = último − primero; puntos fuera = sobre UCL o bajo LCL.', interpretation: 'Rachas pueden indicar deriva y cambios bruscos un cambio de lote, ajuste o medición; investiga causas especiales.', recommendation: 'Verifica orden y medición, segmenta por lote o máquina y no afirmes causalidad solo por tendencia.' }
      : { principle: 'Control limits assess statistical stability; specification limits assess requirements. They are not interchangeable.', formula: 'Change = last − first; out-of-limit count = above UCL or below LCL.', interpretation: 'Same-direction runs may indicate drift; abrupt shifts may indicate a lot change, setting change, or measurement issue.', recommendation: 'Verify ordering and measurement quality, segment by batch or machine, and do not claim causality from a trend alone.' }) : {}
  const timeseriesNotes = topicKey === 'timeseries' ? (lang === 'zh-TW'
    ? { principle: 'lag 與差分描述時間依賴；移動統計平滑短期噪聲，但視窗越大反應越慢。自相關會使獨立樣本假設失效。', formula: 'lag_k=x_{t-k}；Δx_t=x_t−x_{t−1}；rolling mean=Σx／w。', interpretation: '先看時間戳與缺值，再判讀趨勢、週期、自相關與波動；前幾筆 lag 的空值是正常現象。', limits: '小樣本、間隔不規則或未校正時區會使特徵失真；特徵不代表預測能力或因果。', recommendation: '先整理時間軸並以訓練資料計算轉換，避免未來資料洩漏；必要時差分或分層後再建模。' }
    : lang === 'es-MX'
      ? { principle: 'Los retardos y diferencias describen dependencia temporal; ventanas grandes suavizan más pero reaccionan más lento. La autocorrelación rompe la independencia.', formula: 'lag_k=x_{t-k}; Δx_t=x_t−x_{t−1}; media móvil=Σx／w.', interpretation: 'Revisa primero tiempos y faltantes; los primeros retardos nulos son normales. Luego evalúa tendencia, ciclos y volatilidad.', limits: 'Muestras pequeñas, intervalos irregulares o zona horaria incorrecta distorsionan características; no prueban causalidad.', recommendation: 'Calcula transformaciones solo con datos de entrenamiento para evitar fuga; diferencia o segmenta cuando sea necesario.' }
      : { principle: 'Lags and differences describe temporal dependence; larger windows smooth more but react slower. Autocorrelation violates independence assumptions.', formula: 'lag_k=x_{t-k}; Δx_t=x_t−x_{t−1}; rolling mean=Σx／w.', interpretation: 'Check timestamps and missingness first; initial lag nulls are expected. Then assess trend, cycles, dependence, and volatility.', limits: 'Small samples, irregular intervals, or wrong timezone distort features; they do not prove causality.', recommendation: 'Compute transformations using training data only to prevent leakage; difference or segment when needed.' }) : {}
  const grrNotes = topicKey === 'grr' ? (lang === 'zh-TW'
    ? { principle: '重複性（EV）代表同一操作者與量具的設備變異；再現性（AV）代表操作者間差異；%Part 反映零件本身的區分度。', formula: '%GRR=GRR變異／總變異×100%；通常 <10% 可接受、10–30% 視情境、>30% 不可接受。', interpretation: '低 %GRR 較佳；若 EV 主導先改善治具與校正，若 AV 主導則改善操作訓練與方法一致性。%Part 高通常表示零件差異足夠，不是量測系統惡化。', limits: '零件範圍過窄、操作者或重複次數不足、樣本不具代表性，都可能使 GRR 失真；GRR 不是製程能力或因果分析。', recommendation: '依應用重要性設定門檻，改善後以相同研究設計重新量測並比較前後 %GRR。' }
    : lang === 'es-MX'
      ? { principle: 'La repetibilidad (EV) es variación del equipo; la reproducibilidad (AV) es diferencia entre operadores; %Part refleja discriminación entre piezas.', formula: '%GRR=variación GRR／variación total×100%; <10% suele aceptable, 10–30% depende del caso, >30% no aceptable.', interpretation: 'Menor %GRR es mejor; EV dominante requiere fijación y calibración, AV dominante requiere método y capacitación. %Part alto suele indicar rango de piezas suficiente.', limits: 'Rango estrecho, pocos operadores o repeticiones y muestras no representativas distorsionan GRR; no es capacidad ni causalidad.', recommendation: 'Define el umbral según criticidad y repite el estudio con el mismo diseño tras mejorar.' }
      : { principle: 'Repeatability (EV) is equipment variation; reproducibility (AV) is operator difference; %Part reflects part discrimination.', formula: '%GRR=GRR variation／total variation×100%; <10% is usually acceptable, 10–30% depends on context, >30% is unacceptable.', interpretation: 'Lower %GRR is better; dominant EV calls for fixture and calibration work, dominant AV for method and training. High %Part usually means adequate part range.', limits: 'A narrow part range, too few operators or repeats, or unrepresentative samples can distort GRR; it is not capability or causality.', recommendation: 'Set the threshold by application criticality and repeat the same study design after improvement.' }) : {}
  return { ...base, ...topic, ...dataImportNotes, ...distributionNotes, ...trendNotes, ...timeseriesNotes, ...grrNotes, ...(topicKey === 'distribution' ? { steps: distributionSteps } : topicKey === 'trend' ? { steps: trendSteps } : topicKey === 'timeseries' ? { steps: timeseriesSteps } : topicKey === 'grr' ? { steps: grrSteps } : {}), title: '' }
}
